shader_type canvas_item;

uniform vec4 picked : source_color = vec4(0.2, 0.4, 0.6, 1.0);
uniform vec4 typed = vec4(0.2, 0.4, 0.6, 1.0);

void fragment() {
	COLOR = mix(picked, typed, 0.5);
}

shader_type canvas_item;

uniform vec4 tint : source_color = vec4(0.2, 0.4, 0.6, 1.0);

void fragment() {
	COLOR = tint;
}

shader_type spatial;
render_mode unshaded;

uniform sampler2D picture : source_color;

void fragment() {
	ALBEDO = texture(picture, UV).rgb;
}

shader_type spatial;
render_mode unshaded;

uniform sampler2D mask : source_color;
uniform vec3 cream : source_color = vec3(0.98, 0.98, 0.96);
uniform vec3 teal : source_color = vec3(0.37, 0.64, 0.57);

void fragment() {
	float cut = step(0.5, texture(mask, UV).r);
	ALBEDO = mix(cream, teal, cut);
}

shader_type canvas_item;

uniform sampler2D noise_tex;
uniform sampler2D ramp_tex : source_color;
uniform float progress : hint_range(0.0, 1.0) = 0.0;

void fragment() {
	float n = texture(noise_tex, UV).r;
	float cut = mix(-0.1, 1.0, progress);
	if (n <= cut) discard;
	float heat = 1.0 - (n - cut) / 0.1;
	vec3 fire = texture(ramp_tex, vec2(heat, 0.5)).rgb;
	if (heat > 0.0) COLOR.rgb = fire;
}
